 for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;svg+=`<line class="axis" x1="${p.l}" y1="${y(v)}" x2="${w-p.r}" y2="${y(v)}"/><text x="${p.l-11}" y="${y(v)+4}" text-anchor="end">${esc(unit==='%'?percent(v):compact(v))}</text>`;}
 labels.forEach((l,i)=>svg+=`<text x="${x(i)}" y="${h-8}" text-anchor="middle">${esc(l)}</text>`);
 series.forEach(s=>{let started=false,d='';s.values.forEach((v,i)=>{if(v==null){started=false;return}d+=`${started?'L':'M'}${x(i)},${y(v)} `;started=true});svg+=`<path d="${d}" fill="none" stroke="${s.color}" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" ${s.dashed?'stroke-dasharray="7 6"':''}/>`;s.values.forEach((v,i)=>{if(v!=null)svg+=`<circle class="chart-point" tabindex="0" cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="${s.color}" stroke-width="2.5"><title>${esc(labels[i])} · ${esc(s.label)}: ${unit==='%'?percent(v):money(v)+' '+unit}</title></circle>`})});
