function barChart(rows,series,{height=238,unit='₽'}={}){
 if(!rows.length)return empty('За выбранный период нет данных.');const w=760,h=height,p={l:66,r:18,t:12,b:35};const max=Math.max(...rows.map(r=>sum(series.map(s=>Math.max(r[s.key]??0,0)))),1)*1.15;const xstep=(w-p.l-p.r)/rows.length,bw=Math.min(50,xstep*.58),y=v=>h-p.b-(h-p.t-p.b)*v/max;
 let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(series.map(s=>s.label).join(', '))}"><title>${esc(series.map(s=>s.label).join(', '))}</title>`;
 for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line class="axis" x1="${p.l}" y1="${y(v)}" x2="${w-p.r}" y2="${y(v)}"/><text x="${p.l-10}" y="${y(v)+4}" text-anchor="end">${compact(v)}</text>`;}
 rows.forEach((r,i)=>{const x=p.l+xstep*(i+.5)-bw/2;let bottom=0;series.forEach(s=>{let v=r[s.key]??0;if(v>0){svg+=`<rect tabindex="0" class="chart-point" x="${x}" y="${y(bottom+v)}" width="${bw}" height="${Math.max(.5,y(bottom)-y(bottom+v))}" rx="2" fill="${s.color}"><title>${esc(r.label)} · ${esc(s.label)}: ${money(v)} ${unit}</title></rect>`;}bottom+=v});svg+=`<text x="${x+bw/2}" y="${h-8}" text-anchor="middle">${esc(r.label)}</text>`});return svg+'</svg>'+chartLegend(series);
}
function barList(rows,{color=C.blue,suffix='₽',maxRows=8}={}){if(!rows.length)return empty('Нет данных для сравнения.');const max=Math.max(...rows.map(r=>Math.abs(r.value)),1);return `<div class="bar-list">${rows.slice(0,maxRows).map(r=>`<div><div class="bar-label"><span title="${esc(r.label)}">${esc(r.label)}</span><span class="bar-value">${suffix==='%'?percent(r.value):money(r.value)+' '+suffix}</span></div><div class="bar-track"><i style="width:${Math.abs(r.value)/max*100}%;background:${r.color||color}"></i></div></div>`).join('')}</div>`}
