 const b=D.pnl.periods.filter(r=>r.entity===entity&&otherMonths.includes(r.month)&&r[mode==='plan'?'hasPlan':'hasActual']).map(r=>r.month+(mode==='actual'?1:0)).sort((a,b)=>a-b);
