 const compared=state.mode==='compare'||state.mode==='previous',otherMonths=state.mode==='previous'?mm.map(m=>m-1).filter(m=>m>0):mm,otherMode=state.mode==='previous'?'actual':'plan';
 const actual=ratio?pnlRatio(id,state.entity,mm,'actual'):pnlValue(id,state.entity,mm,'actual'),other=ratio?pnlRatio(id,state.entity,otherMonths,otherMode):pnlValue(id,state.entity,otherMonths,otherMode),fmt=ratio?percent:compact;
