 return `<article class="kpi plan-finance"><div class="kpi-label">${esc(label)}<span class="kpi-chip">${icon}</span></div>${compared?`<div class="dual-values"><div><small>Факт</small><b>${fmt(actual)}</b></div><div class="${otherMode==='plan'?'plan-col':''}"><small>${otherMode==='plan'?'План':'Ранее'}</small><b>${fmt(other)}</b></div></div>`:`<div class="kpi-value ${mode==='plan'?'plan-value':''}">${fmt(value)}${ratio||value==null?'':'<small>₽</small>'}</div>`}<div class="kpi-meta">${meta}</div></article>`;
