 for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;svg+=`<line class="axis" x1="${p.l}" x2="${w-p.r}" y1="${y(v)}" y2="${y(v)}"/><text x="${p.l-9}" y="${y(v)+4}" text-anchor="end">${unit==='%'?percent(v):compact(v)}</text>`}
 rows.forEach((r,i)=>{const center=p.l+step*(i+.5);series.forEach((s,j)=>{const v=r[s.key];if(v==null)return;const x=center+(j-series.length/2)*bw;svg+=`<rect class="chart-point" tabindex="0" x="${x}" y="${Math.min(y(v),y(0))}" width="${bw-3}" height="${Math.max(v===0?0:1,Math.abs(y(v)-y(0)))}" rx="3" fill="${s.color}"><title>${esc(r.label)} · ${esc(s.label)}: ${unit==='%'?percent(v):exact(v)+' '+unit}</title></rect>`});svg+=`<text x="${center}" y="${h-10}" text-anchor="middle">${esc(r.label)}</text>`});
 lines.forEach(l=>{let d='',started=false;l.values.forEach((v,i)=>{if(v==null){started=false;return}const x=p.l+step*(i+.5);d+=`${started?'L':'M'}${x},${y(v)} `;started=true;svg+=`<circle class="chart-point" tabindex="0" cx="${x}" cy="${y(v)}" r="3" fill="${l.color}"><title>${esc(rows[i].label)} · ${esc(l.label)}: ${exact(v)} ${unit}</title></circle>`});svg+=`<path d="${d}" stroke="${l.color}" stroke-width="2.5" fill="none" ${l.dashed?'stroke-dasharray="5 5"':''}/>`});return svg+'</svg>'+chartLegend([...series,...lines]);
