 if(act==null)messages.push(['info','i',`<b>${months[month-1]}: факт ОПиУ не заполнен.</b> Прогноз показан отдельно, без нулевого «факта».`]);else if(plan==null)messages.push(['info','i','<b>План этого периода не заполнен.</b> Для динамики выберите «Прошлый месяц»; план источника начинается с сентября.']);
