 const controls=D.pnl.checks.filter(c=>c.status&&c.status!=='OK');if(controls.length)messages.push(['','!',`<b>Контроли ОПиУ требуют внимания.</b> ${controls.map(c=>`${esc(c.label)}: ${exact(c.value)}`).join('; ')}. <button data-open-sources>Источник →</button>`]);
 const reconciled=D.cash.months.filter(m=>m.hasData).every(m=>Math.abs(m.reconciliation)<.01);if(reconciled)messages.push(['ok','✓','<b>ДДС сходится.</b> Остатки проверены по всем заполненным месяцам.']);
 return messages.slice(0,5).map(([cl,s,html])=>`<div class="owner-row"><i class="${cl}">${s}</i><p>${html}</p></div>`).join('');
