function displayArticle(article,entity=state.entity,mm=activeMonths(),mode=state.mode){
 mode=['compare','previous'].includes(mode)?'actual':mode;
 if(article.kind!=='ratio')return pnlValue(article.id,entity,mm,mode);
 const rows=D.pnl.rows.filter(r=>r.entity===entity&&r.article===article.id&&mm.includes(r.month)&&r[mode==='plan'?'hasPlan':'hasActual']&&r[mode]!=null);
 const weights=rows.map(r=>({value:r[mode],weight:pnlValue(37,entity,[r.month],mode)}));const base=sum(weights.map(r=>r.weight));return base?sum(weights.map(r=>r.value*r.weight))/base:null;
}
function subnav(items,key){return `<div class="view-tabs" role="group" aria-label="Вид отчёта">${items.map(([v,l])=>`<button data-view-key="${key}" data-view="${v}" class="${state[key]===v?'active':''}">${esc(l)}</button>`).join('')}</div>`}
function tableHTML(columns,rows,{classes='',emptyText='По выбранным условиям нет записей.'}={}){return rows.length?`<div class="table-wrap"><table class="data-table ${classes}"><thead><tr>${columns.map(c=>`<th class="${c.numeric?'number':''}">${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(c=>`<td class="${c.numeric?'number':''}">${c.render?c.render(r):esc(r[c.key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty(emptyText)}
function pages(rows,size=40){const count=Math.max(1,Math.ceil(rows.length/size));state.page=Math.min(state.page,count);return {rows:rows.slice((state.page-1)*size,state.page*size),footer:`<div class="pagination"><span>${rows.length?`${(state.page-1)*size+1}–${Math.min(state.page*size,rows.length)} из ${money(rows.length)}`:'0 записей'}</span><div><button class="button quiet" data-page="${state.page-1}" ${state.page===1?'disabled':''}>← Назад</button><span>${state.page} / ${count}</span><button class="button quiet" data-page="${state.page+1}" ${state.page===count?'disabled':''}>Дальше →</button></div></div>`}}
function searchInput(key,label){return `<input type="search" data-search="${key}" aria-label="${esc(label)}" placeholder="${esc(label)}" value="${esc(state[key])}">`}
function stateSelect(key,label,options){return `<div class="field"><label for="${key}">${esc(label)}</label><select id="${key}" data-state="${key}">${options.map(([v,l])=>`<option value="${esc(v)}" ${state[key]===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function groupSum(rows,key,value){const m=new Map();for(const r of rows){const k=key(r);m.set(k,(m.get(k)||0)+value(r))}return [...m].map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value)}
