 currentExport=people.map(r=>({Имя:r.name,Роль:r.role,Точка:r.site,Период:periodLabel(),Начислено:r.total,Выплачено:r.paid,'К выплате':r.debt,ПоследняяНеделя:r.last}));const p=pages(people);
