function supplierBase(){return [...D.suppliers.weekly.map(r=>({...r,type:'ayk',supplier:'АЙК',document:'Недельный итог'})),...D.suppliers.invoices.map(r=>({...r,type:'manufacturer'}))].filter(r=>(state.supplierType==='all'||r.type===state.supplierType)&&`${r.supplier} ${r.document}`.toLocaleLowerCase('ru').includes(state.supplierSearch.toLocaleLowerCase('ru')))}
