 const cols=[{label:'Дата / документ',render:r=>`${date(r.date)}<div class="secondary">${esc(r.document)}</div>`},{label:'Поставщик',render:r=>`<button class="row-link" data-supplier-row="${r.id}">${esc(r.supplier)} ↗</button>`},{label:'Сумма, ₽',numeric:true,render:r=>exact(r.amount)},{label:'Оплатить до',render:r=>date(r.due)},{label:'Статус',render:r=>`<span class="status ${r.paid?'paid':r.overdue?'overdue':'debt'}">${r.paid?'Оплачено':r.overdue?'Просрочено':'Не оплачено'}</span>`}];
 currentExport=selected.map(r=>({Дата:r.date,Поставщик:r.supplier,Документ:r.document,Сумма:r.amount,Срок:r.due,Статус:r.paid?'Оплачено':'Не оплачено',Ячейка:r.sourceCell}));
 const series=activeMonths().map(m=>{const rr=rows.filter(r=>r.month===m);return {label:shortMonths[m-1],paid:sum(rr.filter(r=>r.paid).map(r=>r.amount)),debt:sum(rr.filter(r=>!r.paid).map(r=>r.amount)),count:rr.length}}).filter(r=>r.count);
 const overdue=sum(debts.filter(r=>r.overdue).map(r=>r.amount));const soon=sum(debts.filter(r=>r.due&&r.due>=D.asOf&&((new Date(r.due)-new Date(D.asOf))/864e5)<=7).map(r=>r.amount));
 return heading('Поставщики','АЙК отдельно, документы производителей отдельно. Статус оплаты — по цвету суммы в таблице.','suppliers')+controls({entity:false,mode:false})+`<div class="table-toolbar">${stateSelect('supplierType','Реестр',[['all','Все поставщики'],['ayk','АЙК · товар'],['manufacturer','От производителя']])}${searchInput('supplierSearch','Найти поставщика или документ')}</div><div class="kpi-grid">${kpi('Долг по документам 2026',money(debt),`На ${date(D.asOf)} · весь 2026, независимо от периода`,'accent')}${kpi('Оплачено по документам периода',money(paid),periodLabel())}${kpi('Просрочено · 2026',money(overdue),'Только документы с указанным сроком')}${kpi('Оплатить в ближайшие 7 дней',money(soon),'От даты снимка')}</div><div class="mini-grid">${mini('АЙК · текущий долг',sum(debts.filter(r=>r.type==='ayk').map(r=>r.amount)),'В выбранном реестре и поиске','□')}${mini('Производители · текущий долг',sum(debts.filter(r=>r.type==='manufacturer').map(r=>r.amount)),'В выбранном реестре и поиске','≡')}${mini('Не оплачено по документам периода',sum(rows.filter(r=>!r.paid).map(r=>r.amount)),periodLabel(),'↔')}</div><div class="grid">${panel('Документы по месяцам','Оплаченные и открытые суммы · по дате документа, не дате платежа',barChart(series,[{key:'paid',label:'Оплачено',color:C.emerald},{key:'debt',label:'Не оплачено',color:C.amber}]),'span8')}${panel('Структура текущего долга','Документы 2026 · выбранный реестр и поиск',barList(groupSum(debts,r=>r.supplier,r=>r.amount),{color:C.amber}),'span4')}${panel('Документы и недельные итоги',`${periodLabel()} · ${money(selected.length)} записей`,`<div class="table-toolbar">${stateSelect('supplierStatus','Статус',[['all','Все статусы'],['paid','Оплачено'],['debt','Не оплачено'],['overdue','Просрочено']])}<span class="table-meta">Нажмите поставщика для деталей</span></div>`+tableHTML(cols,p.rows)+p.footer,'span12')}</div>`+(legacy.length?`<details><summary>Старые неоплаченные записи · ${money(old)} ₽</summary><div>${tableHTML(cols,legacy)}</div></details>`:'')+issueBox(D.suppliers.issues,'suppliers')+`<div class="note">АЙК считается один раз по итоговой сумме недели: промежуточные суммы точек не прибавляются повторно. На графиках — документы 2026 года. Остаток долга — состояние цветовых отметок на дату загрузки, исторический долг на конец прошлых месяцев из этих данных восстановить нельзя.</div>`;
